import { getA0LessonKnowledge, A0_KNOWLEDGE_UNITS, type A0LessonKnowledge } from './a0KnowledgeMap'

export interface A0VocabularyItem {
  word: string
  ipa: string
  meaning: string
  partOfSpeech: string
  example: string
  exampleTranslation: string
  usageNote?: string
}

export interface A0AlphabetLetter {
  letter: string
  letterName: string
  ipa: string
  note?: string
}

export interface A0SentencePattern {
  name: string
  formula: string
  components: { label: string; description: string }[]
  explanation: string
  example: string
  exampleTranslation: string
  commonMistake: string
}

export interface A0Exercise {
  id: string
  type: 'multiple-choice' | 'guided-output'
  prompt: string
  options?: string[]
  answer?: string
  answerIndex?: number
  explanation: string
  modelAnswer?: string
  selfCheck?: string[]
}

export interface A0Lesson {
  id: string
  code: string
  title: string
  title_vi: string
  level: 'A0'
  module_id: string
  order: number
  objectives: string[]
  introduction: string
  alphabet?: A0AlphabetLetter[]
  vocabulary: A0VocabularyItem[]
  explanations: { heading: string; text: string }[]
  sentence_patterns: A0SentencePattern[]
  pronunciation: { focus: string; explanation: string; examples: string[]; commonConfusions: string[]; practice: string[] }
  listening: { audioStatus: 'pending-integration'; purpose: string; task: string; script: string; answerKey: string }
  speaking_tasks: { prompt: string; steps: string[]; sentenceStarter?: string; successCriteria: string[] }[]
  ai_conversation: { status: 'coming-soon'; scenario: string; aiRole: string; learnerRole: string; goal: string; openingQuestion: string; openingQuestionTranslation: string; allowedVocabulary: string[]; allowedPatterns: string[]; supportStrategy: string[]; postConversationSummary: string[] }
  exercises: A0Exercise[]
  review: string[]
  assessment: { task: string; criteria: string[]; passRule: string; limitation: string }
  prerequisites: string[]
  related_lessons: string[]
  knowledge: A0LessonKnowledge
}

export interface A0Module {
  id: string
  code: string
  title: string
  objective: string
  lessons: A0Lesson[]
}

interface RawVocabularyItem { word: string; meaning: string; example?: string }
interface RawExercise { prompt: string; options: string[]; answerIndex: number; explanation: string }
interface RawA0Lesson {
  id: string; code: string; title: string; objective: string; introduction: string;
  vocabulary?: RawVocabularyItem[]; explanation: string; patterns?: string[];
  pronunciation?: string; listening?: string; speaking: string; exercise: RawExercise;
  review: string[]; assessment: string;
}
interface RawA0Module { id: string; code: string; title: string; objective: string; lessons: RawA0Lesson[] }

const lesson = (
  code: string,
  title: string,
  objective: string,
  introduction: string,
  explanation: string,
  speaking: string,
  exercise: RawExercise,
  options: {
    vocabulary?: RawVocabularyItem[]
    patterns?: string[]
    pronunciation?: string
    listening?: string
    review?: string[]
    assessment?: string
  } = {},
): RawA0Lesson => ({
  id: code.toLowerCase(), code, title, objective, introduction, explanation, speaking, exercise,
  vocabulary: options.vocabulary, patterns: options.patterns, pronunciation: options.pronunciation,
  listening: options.listening, review: options.review ?? [objective, explanation],
  assessment: options.assessment ?? `Tự nói hoặc viết một ví dụ thể hiện mục tiêu: ${objective.toLowerCase()}`,
})

